    public void modifiedField(FieldId _fieldId)
    {
        next modifiedField(_fieldId);

        switch(_fieldId)
        {
            case fieldNum(VendInvoiceInfoLine, ReceiveNow):
            case fieldNum(VendInvoiceInfoLine, PdsCWReceiveNow):           
            case fieldNum(VendInvoiceInfoLine, PurchPrice):
                this.initReasonCode(_fieldId);
                break;
        }

    }

    public Query initReasonQuery(boolean _isPriceVariance, boolean _isQtyVariance, boolean _isCatchWeight, boolean _isOver)
    {
        Query query;
        QueryBuildDataSource qbdsReasonTable;

        query = new Query();
        qbdsReasonTable = query.addDataSource(tableNum(ReasonTable));
        qbdsReasonTable.firstOnly(true);

        qbdsReasonTable.addRange(fieldNum(ReasonTable, Vend)).value(queryValue(NoYes::Yes));
        qbdsReasonTable.addRange(fieldNum(ReasonTable, METInvoiceMatch)).value(queryValue(NoYes::Yes));
        qbdsReasonTable.addRange(fieldNum(ReasonTable, METApprove)).value(queryValue(NoYes::No));

        if(_isPriceVariance && _isQtyVariance)
        {
            qbdsReasonTable.addRange(fieldNum(ReasonTable, METPriceVar)).value(queryValue(NoYes::Yes));

            if(_isCatchWeight)
            {
                qbdsReasonTable.addRange(fieldNum(ReasonTable, METRWQty)).value(queryValue(NoYes::Yes));
            }
            else
            {
                qbdsReasonTable.addRange(fieldNum(ReasonTable, METQtyVar)).value(queryValue(NoYes::Yes));
            }
        }
        else if(_isQtyVariance)
        {
            qbdsReasonTable.addRange(fieldNum(ReasonTable, METOver)).value(queryValue(NoYes::Yes));

            if(_isCatchWeight)
            {
                qbdsReasonTable.addRange(fieldNum(ReasonTable, METRWQty)).value(queryValue(NoYes::Yes));
            }
            else
            {
                qbdsReasonTable.addRange(fieldNum(ReasonTable, METQtyVar)).value(queryValue(NoYes::Yes));
            }
        }
        else if(_isPriceVariance)
        {
            qbdsReasonTable.addRange(fieldNum(ReasonTable, METPriceVar)).value(queryValue(NoYes::Yes));

            if(_isOver)
            {
                qbdsReasonTable.addRange(fieldNum(ReasonTable, METOver)).value(queryValue(NoYes::Yes));
            }
            else
            {
                qbdsReasonTable.addRange(fieldNum(ReasonTable, METUnder)).value(queryValue(NoYes::Yes));
            }
        }

        return query; 
    }

    public void initReasonCode(FieldId _fieldId)
    {
        Query   query; 
        boolean catchWeight;
        boolean over;

        if(_fieldId == fieldNum(VendInvoiceInfoLine, PdsCWReceiveNow) ||
                this.PdsCWReceiveNow)
        {
            catchWeight = true;
        }

        if(this.checkIfQuantityMatch() == LastMatchVarianceOptions::Warning &&
           this.priceVarianceStatus() == LastMatchVarianceOptions::Warning)
        {
            query = this.initReasonQuery(true, true, catchWeight, false);
        }
        else if(this.checkIfQuantityMatch() == LastMatchVarianceOptions::Warning &&
                (this.ReceiveNow > this.purchQtyMatched() || this.PdsCWReceiveNow > this.pdsCWQtyMatched()))
        {
            query = this.initReasonQuery(false, true, catchWeight, true);
        }
        else if(this.priceVarianceStatus() == LastMatchVarianceOptions::Warning)
        {
            if(this.priceVariancePercent() > 0)
            {
                over = true;
            }

            query = this.initReasonQuery(true, false, catchWeight, over);
        }

        if(query)
        {
            QueryRun queryRun = new QueryRun(query);

            if(queryRun.next())
            {
                ReasonTable reason = queryRun.get(tableNum(ReasonTable));

                if(reason)
                {
                    this.ReasonTableRef = ReasonTableRef::createReasonTableRef(reason.Reason, reason.Description);
                    this.MetAutoApprove = reason.METApprove;
                    this.MetClaimLine   = reason.METClaim;
                    this.MetExtComment  = reason.MetExtComment;
                    this.MetMultiple    = reason.MetMultiple;
                }
                else
                {
                    warning("@MET:ReasonCodeNotSetup");
                }
            }
        }
        else
        {
            this.ReasonTableRef = 0;
            this.MetAutoApprove = NoYes::No;
            this.MetClaimLine   = NoYes::No;
            this.MetExtComment  = '';
            this.MetMultiple    = NoYes::No;
        }
    }
